import{_ as a,a as r,c as i,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"亮剑","description":"军人李云龙以强烈个性、战场经验和敢于承担风险的作风带领部队，在不同历史阶段面对作战、组织与个人生活的挑战。赵刚、楚云飞等人物从不同立场与他形成长期的理解和冲突。","frontmatter":{"title":"亮剑","description":"军人李云龙以强烈个性、战场经验和敢于承担风险的作风带领部队，在不同历史阶段面对作战、组织与个人生活的挑战。赵刚、楚云飞等人物从不同立场与他形成长期的理解和冲突。","media":{"category":"series","year":2005,"doubanRating":9.5,"ratingCheckedAt":"2026-10-31","ratingSource":"https://www.douban.com/doulist/134440083/","ratingSourceType":"豆瓣公开片单"},"showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"影视导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"影视 · 电视剧","summary":"军人李云龙以强烈个性、战场经验和敢于承担风险的作风带领部队，在不同历史阶段面对作战、组织与个人生活的挑战。赵刚、楚云飞等人物从不同立场与他形成长期的理解和冲突。","status":"active","related":[{"title":"大明王朝1566","link":"/life/personal/media/series/ming-dynasty-1566","kind":"影视导读","scope":"general","audience":"general"},{"title":"是，大臣 第一季","link":"/life/personal/media/series/yes-minister-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"红楼梦（1987）","link":"/life/personal/media/series/dream-of-the-red-chamber-1987","kind":"影视导读","scope":"general","audience":"general"},{"title":"西游记（1986）","link":"/life/personal/media/series/journey-to-the-west-1986","kind":"影视导读","scope":"general","audience":"general"},{"title":"老友记 第一季","link":"/life/personal/media/series/friends-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"请回答1988","link":"/life/personal/media/series/reply-1988","kind":"影视导读","scope":"general","audience":"general"},{"title":"白色巨塔（2003）","link":"/life/personal/media/series/the-white-tower-2003","kind":"影视导读","scope":"general","audience":"general"},{"title":"毛骗 终结篇","link":"/life/personal/media/series/moral-peanuts-finale","kind":"影视导读","scope":"general","audience":"general"},{"title":"武林外传","link":"/life/personal/media/series/my-own-swordsman","kind":"影视导读","scope":"general","audience":"general"},{"title":"我的团长我的团","link":"/life/personal/media/series/my-chief-and-my-regiment","kind":"影视导读","scope":"general","audience":"general"},{"title":"非自然死亡","link":"/life/personal/media/series/unnatural","kind":"影视导读","scope":"general","audience":"general"},{"title":"机智医生生活 第一季","link":"/life/personal/media/series/hospital-playlist-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"琅琊榜","link":"/life/personal/media/series/nirvana-in-fire","kind":"影视导读","scope":"general","audience":"general"},{"title":"后宫·甄嬛传","link":"/life/personal/media/series/empresses-in-the-palace","kind":"影视导读","scope":"general","audience":"general"},{"title":"漫长的季节","link":"/life/personal/media/series/the-long-season","kind":"影视导读","scope":"general","audience":"general"},{"title":"我们与恶的距离","link":"/life/personal/media/series/the-world-between-us","kind":"影视导读","scope":"general","audience":"general"}],"prev":{"text":"机智医生生活 第一季","link":"/life/personal/media/series/hospital-playlist-season-1"},"next":{"text":"琅琊榜","link":"/life/personal/media/series/nirvana-in-fire"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"机智医生生活 第一季","link":"/life/personal/media/series/hospital-playlist-season-1"},"next":{"text":"琅琊榜","link":"/life/personal/media/series/nirvana-in-fire"}},"headers":[],"relativePath":"life/personal/media/series/bright-sword.md","filePath":"life/personal/media/series/bright-sword.md"}'),n={name:"life/personal/media/series/bright-sword.md"};function l(s,e,d,o,p,h){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="亮剑" tabindex="-1">亮剑 <a class="header-anchor" href="#亮剑" aria-label="Permalink to &quot;亮剑&quot;">​</a></h1><p><a href="./../overview">影视总览</a> · <a href="./overview">电视剧片单</a></p><h2 id="基本资料" tabindex="-1">基本资料 <a class="header-anchor" href="#基本资料" aria-label="Permalink to &quot;基本资料&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>信息</th></tr></thead><tbody><tr><td>原名 / 别名</td><td>亮剑 / Drawing Sword</td></tr><tr><td>年份 / 地区</td><td>2005 / 中国大陆</td></tr><tr><td>类型</td><td>战争 / 剧情</td></tr><tr><td>导演 / 主创</td><td>张前、陈健</td></tr><tr><td>主要演员 / 配音</td><td>李幼斌、何政军、张光北</td></tr><tr><td>篇幅 / 版本</td><td>30 集，单集约 42 分钟</td></tr><tr><td>豆瓣参考评分</td><td><strong>9.5 / 10</strong></td></tr><tr><td>评分依据</td><td><a href="https://www.douban.com/doulist/134440083/" target="_blank" rel="noopener noreferrer">豆瓣用户维护的电视剧片单</a>（豆瓣公开片单）</td></tr><tr><td>查询日期</td><td>2026-10-31</td></tr></tbody></table><p>评分为本次查询可读取的豆瓣页面值，网页缓存可能滞后，不能保证与此刻实时值一致。 篇幅按常见版本作近似说明，片头、花絮及剪辑差异可能影响播放时长。</p><h2 id="创作背景与资料" tabindex="-1">创作背景与资料 <a class="header-anchor" href="#创作背景与资料" aria-label="Permalink to &quot;创作背景与资料&quot;">​</a></h2><p>本剧根据都梁同名小说改编，2005年播出。公开作品资料列出了都梁、江奇涛的编剧身份以及李幼斌等人的表演信息。电视剧取舍了小说内容，不能把原著后段全部经历直接视为荧屏已经呈现。<a href="https://www.cnhubei.com/xwzt/2011/jd90/hbhsjd/hsys/201105/t1693756.shtml" target="_blank" rel="noopener noreferrer">作品与创作资料</a></p><p>李云龙的吸引力既来自果断，也来自粗粝、好胜和不愿服输。剧作让这些特征在不同场合产生不同结果，人物才具有超出英雄口号的张力。</p><h2 id="剧情介绍" tabindex="-1">剧情介绍 <a class="header-anchor" href="#剧情介绍" aria-label="Permalink to &quot;剧情介绍&quot;">​</a></h2><p>军人李云龙以强烈个性、战场经验和敢于承担风险的作风带领部队，在不同历史阶段面对作战、组织与个人生活的挑战。赵刚、楚云飞等人物从不同立场与他形成长期的理解和冲突。</p><p>剧集用鲜明的人物语言和战场行动建立感染力，同时把指挥者的魅力、纪律与责任放在一起讨论。私人情绪与集体目标并不总能一致，这也构成李云龙形象中的重要矛盾。</p><h2 id="特色与看点" tabindex="-1">特色与看点 <a class="header-anchor" href="#特色与看点" aria-label="Permalink to &quot;特色与看点&quot;">​</a></h2><h3 id="_1-叙事与人物" tabindex="-1">1. 叙事与人物 <a class="header-anchor" href="#_1-叙事与人物" aria-label="Permalink to &quot;1. 叙事与人物&quot;">​</a></h3><p>李云龙的直觉与赵刚的原则互相补充，使领导力不只表现为一个人的强势。可以比较两人处理士气、纪律与具体人的方式。</p><h3 id="_2-主题与表达" tabindex="-1">2. 主题与表达 <a class="header-anchor" href="#_2-主题与表达" aria-label="Permalink to &quot;2. 主题与表达&quot;">​</a></h3><p>与楚云飞的关系让对手之间的尊重与立场差异同时存在。故事具有传奇化表达，观看战争桥段时宜区分戏剧节奏、人物塑造与真实军事史。</p><h2 id="三组关系支撑人物" tabindex="-1">三组关系支撑人物 <a class="header-anchor" href="#三组关系支撑人物" aria-label="Permalink to &quot;三组关系支撑人物&quot;">​</a></h2><p>李云龙与赵刚的合作，把军事行动和政治、组织责任放在一起。两人不总同意，却逐渐知道对方在哪些事情上可靠。与楚云飞的相遇则让对手之间的欣赏与立场冲突并存，能力获得尊重，并不取消现实分歧。</p><p>秀芹与田雨等关系让人物进入战争之外的生活，暴露他在表达、情感与家庭中的局限。能够指挥行动，不代表已经学会平等相处，这种不一致也是观看人物的重要部分。</p><h2 id="内容推进与代表段落" tabindex="-1">内容推进与代表段落 <a class="header-anchor" href="#内容推进与代表段落" aria-label="Permalink to &quot;内容推进与代表段落&quot;">​</a></h2><p>早期战斗建立部队风格和资源匮乏，后续战事让私人损失进入公共决定，战争阶段变化又使指挥者必须重新学习。建议把每次作战前掌握的信息、资源与目标记下来，避免只在胜负之后赞叹胆量。</p><p>骑兵、伏击和部队整训等段落使用鲜明动作建立记忆，赵刚与李云龙的争论则补上纪律和责任。最值得比较的不是谁的声音更大，而是谁在讨论目标，谁在追问会由哪些人承担代价。</p><h2 id="表演与语言" tabindex="-1">表演与语言 <a class="header-anchor" href="#表演与语言" aria-label="Permalink to &quot;表演与语言&quot;">​</a></h2><p>李幼斌的语速、停顿和身体动作，让粗话、玩笑和突然的沉默都带着人物经验。部队内部的称呼与相互挖苦建立熟悉感，牺牲才不只剩名单上的数字。</p><p>作品也具有传奇化表达，敌我能力与行动效果为人物塑造作过选择。喜欢它的感染力，不意味着需要将所有桥段当作历史事实或战术范例。</p><h2 id="评价与重看建议" tabindex="-1">评价与重看建议 <a class="header-anchor" href="#评价与重看建议" aria-label="Permalink to &quot;评价与重看建议&quot;">​</a></h2><p>本剧长处在于鲜明人物和容易进入的故事节奏，局限是某些复杂历史条件被简化为少数人的判断与较量。重看可以追踪赵刚这条线：他如何劝阻、合作和承担，而不把原则角色当成阻止英雄发挥的障碍。</p><p>若进一步阅读原著，适合比较电视剧保留了哪些经历、删掉哪些阶段。改编边界越清楚，越容易理解荧屏版人物为什么呈现出特定的精神面貌。</p><h2 id="适合谁看与观看建议" tabindex="-1">适合谁看与观看建议 <a class="header-anchor" href="#适合谁看与观看建议" aria-label="Permalink to &quot;适合谁看与观看建议&quot;">​</a></h2><p>适合喜欢个性鲜明的军事群像与直接叙事的人。含枪战、牺牲与复仇情绪；不要把所有行动都视为现实指挥范本，可重点观察人物怎样面对决定的代价。</p><h2 id="看后思考" tabindex="-1">看后思考 <a class="header-anchor" href="#看后思考" aria-label="Permalink to &quot;看后思考&quot;">​</a></h2><p>敢于冒险与对集体负责如何同时成立？一个具有个人魅力的领导者为什么仍需要不同意见？</p><p>创作事实见段落所附来源；人物、场景与评价部分为本站观影分析，不代表主创唯一解释。正文保留主要故事体验，不展开关键结局。评分用于辅助选片，不代表每位观众的感受。</p><h2 id="资料与复核入口" tabindex="-1">资料与复核入口 <a class="header-anchor" href="#资料与复核入口" aria-label="Permalink to &quot;资料与复核入口&quot;">​</a></h2><ul><li><a href="https://www.douban.com/doulist/134440083/" target="_blank" rel="noopener noreferrer">豆瓣用户维护的电视剧片单</a>：本页评分依据；查询于 2026-10-31。</li><li><a href="https://movie.douban.com/subject/2254648/" target="_blank" rel="noopener noreferrer">《亮剑》豆瓣条目</a>：版本与后续评分复核入口；部分条目可能要求验证。</li></ul><p><a href="./overview">返回电视剧片单</a> · <a href="./../overview">返回影视总览</a></p>',36)])])}const m=a(n,[["render",l]]);export{u as __pageData,m as default};
